func (this *Image) CreateMask() {
	var width int32 = this.width
	var height int32 = this.height
	var stride int32 = gtk.CairoCairo_image_surface_get_stride(this.Surface)
	var surfaceData int64 = gtk.CairoCairo_image_surface_get_data(this.Surface)
	var oa int32
	var or int32
	var og int32
	var ob int32
	var tr int32
	var tg int32
	var tb int32
	if gtk.OSBIG_ENDIAN {
		oa = 0
		or = 1
		og = 2
		ob = 3
		tr = (this.transparentPixel >> 24) & 0xFF
		tg = (this.transparentPixel >> 16) & 0xFF
		tb = (this.transparentPixel >> 8) & 0xFF
	} else {
		oa = 3
		or = 2
		og = 1
		ob = 0
		tr = (this.transparentPixel >> 16) & 0xFF
		tg = (this.transparentPixel >> 8) & 0xFF
		tb = (this.transparentPixel >> 0) & 0xFF
	}
	var srcData []int8 = make([]int8, stride*height)
	gtk.CMemmoveOverload8(srcData, surfaceData, int64(int32(len(srcData))))
	var offset int32 = 0
	for y := int32(0); y < height; y++ {
		{
			var x int32 = 0
			for ; x < width; func() {
				x++
				offset += 4
			}() {
				var a int32 = int32(srcData[offset+oa]) & 0xFF
				var r int32 = int32(srcData[offset+or]) & 0xFF
				var g int32 = int32(srcData[offset+og]) & 0xFF
				var b int32 = int32(srcData[offset+ob]) & 0xFF
				if r == tr && g == tg && b == tb {
					b = 0
					g = b
					r = g
					a = r
				} else {
					a = 0xff
				}
				srcData[offset+oa] = int8(a)
				srcData[offset+or] = int8(r)
				srcData[offset+og] = int8(g)
				srcData[offset+ob] = int8(b)
			}
		}
	}
	gtk.CMemmove(surfaceData, srcData, int64(int32(len(srcData))))
}

